  const amountAfterDiscount = 10000 - 1000;
  const expectedVat = Math.round(amountAfterDiscount * 21 / 100 * 1e6) / 1e6;
  assert.equal(vat, 1890);
});

test('lineVat handles different VAT rates', () => {
